@Mod.EventBusSubscriber(modid="thaumcraft")
public final class EldritchProbe {
 public static final BlockPos P=new BlockPos(40008,180,8);public static volatile boolean ready;static int ticks,stage;static ServerPlayer actor;static EldritchMob saved;static UUID savedId;static final List<thaumcraft.taint.TaintedMob> giants=new ArrayList<>();static boolean giantLoot;static final List<Entity> joined=new ArrayList<>();
 static String mode(){return System.getProperty("thaumcraft.eldritchProbe","");}static void check(boolean ok,String m){if(!ok)throw new AssertionError(m);}
 @SubscribeEvent public static void join(net.minecraftforge.event.entity.EntityJoinLevelEvent e){if(!mode().isEmpty())joined.add(e.getEntity());}
 static CompoundTag tag(ServerLevel l,Entity e){var out=TagValueOutput.createWithContext(ProblemReporter.DISCARDING,l.registryAccess());e.saveWithoutId(out);return out.buildResult();}
 static void load(ServerLevel l,Entity e,CompoundTag t){e.load(TagValueInput.create(ProblemReporter.DISCARDING,l.registryAccess(),t));}
 static EldritchMob mob(ServerLevel l,EldritchMob.Kind k,int dx){var m=new EldritchMob(EldritchContent.TYPES.get(k).get(),l,k);m.setNoAi(true);m.setNoGravity(true);m.setPos(P.getX()+dx,P.getY(),P.getZ());var data=tag(l,m);data.putInt("eldritch_arrival",0);load(l,m,data);check(l.addFreshEntity(m),"Cannot spawn "+k);return m;}
 static ServerPlayer fake(ServerLevel l){var p=new ServerPlayer(l.getServer(),l,new GameProfile(UUID.fromString("2e0ad0aa-a3e7-4b40-9d5f-c4c7a8967a56"),"EldritchTest"),ClientInformation.createDefault());new net.minecraft.server.network.ServerGamePacketListenerImpl(l.getServer(),new net.minecraft.network.Connection(net.minecraft.network.protocol.PacketFlow.SERVERBOUND),p,net.minecraft.server.network.CommonListenerCookie.createInitial(p.getGameProfile(),false));for(int n=0;n<60;n++)p.connection.tickClientLoadTimeout();p.setPos(P.getX(),P.getY(),P.getZ()+7);p.getAttribute(Attributes.MAX_HEALTH).setBaseValue(1000);p.setHealth(1000);l.addNewPlayer(p);return p;}
 static void force(ServerLevel l){for(int x=-2;x<=2;x++)for(int z=-2;z<=2;z++){l.setChunkForced((P.getX()>>4)+x,(P.getZ()>>4)+z,true);l.getChunk((P.getX()>>4)+x,(P.getZ()>>4)+z);}}
 static void rules(ServerLevel l){thaumcraft.config.ThaumcraftConfig.allowChampionMobs.set(false);for(var old:l.getEntitiesOfClass(net.minecraft.world.entity.Mob.class,new net.minecraft.world.phys.AABB(P).inflate(64)))old.discard();
  check(l.registryAccess().lookupOrThrow(net.minecraft.core.registries.Registries.BIOME).get(thaumcraft.content.SimpleContent.id("eerie")).isPresent(),"Eerie missing");check(l.registryAccess().lookupOrThrow(net.minecraft.core.registries.Registries.BIOME).get(thaumcraft.content.SimpleContent.id("eldritch")).isPresent(),"Outer biome missing");
  check(EldritchContent.EGGS.size()==9,"Spawn eggs missing");for(var k:EldritchContent.TYPES.keySet()){var m=mob(l,k,k.ordinal()*4-16);check(m.getMaxHealth()==k.health&&m.getAttributeBaseValue(Attributes.ATTACK_DAMAGE)==k.damage,"Wrong attributes "+k);var copy=new EldritchMob(EldritchContent.TYPES.get(k).get(),l,k);load(l,copy,tag(l,m));check(copy.getHealth()==m.getHealth()&&copy.phase()==m.phase(),"NBT roundtrip "+k);m.discard();}
  for(var k:EldritchContent.ZOMBIES.keySet()){var zombie=new BrainyZombie(EldritchContent.ZOMBIES.get(k).get(),l,k);zombie.setNoAi(true);zombie.setNoGravity(true);zombie.setPos(P.getX()-20,P.getY(),P.getZ());check(zombie.getMaxHealth()==k.health,"Wrong native zombie health "+k);check(l.addFreshEntity(zombie),"Cannot add native zombie");if(k==EldritchMob.Kind.GIANT){for(int n=0;n<15;n++){zombie.damageCooldownTime=0;zombie.hurtServer(l,l.damageSources().magic(),.1F);}zombie.tick();check(zombie.anger()>1&&zombie.getAttributeValue(Attributes.SCALE)>2,"Giant anger did not enlarge native collision");}var copy=new BrainyZombie(EldritchContent.ZOMBIES.get(k).get(),l,k);load(l,copy,tag(l,zombie));check(copy.anger()==zombie.anger(),"Native zombie anger did not save");zombie.discard();}
  for(var k:List.of(EldritchMob.Kind.LEADER,EldritchMob.Kind.GOLEM,EldritchMob.Kind.WARDEN,EldritchMob.Kind.PORTAL)){var victim=mob(l,k,20);var data=tag(l,victim);data.putInt("eldritch_phase",1);data.putBoolean("eldritch_ward_broken",true);load(l,victim,data);victim.setAbsorptionAmount(0);int start=joined.size();for(int n=0;n<50&&victim.isAlive();n++){victim.damageCooldownTime=0;victim.hurtServer(l,l.damageSources().fellOutOfWorld(),35);}check(!victim.isAlive(),"Boss did not die "+k);var items=joined.subList(start,joined.size()).stream().filter(x->x instanceof ItemEntity).map(x->((ItemEntity)x).getItem()).toList();int pearl=items.stream().filter(x->x.is(thaumcraft.content.SimpleContent.ITEMS.get("primordial_pearl").get())).mapToInt(ItemStack::getCount).sum();int bags=items.stream().filter(x->x.is(thaumcraft.content.SimpleContent.ITEMS.get("loot_bag_rare").get())).mapToInt(ItemStack::getCount).sum();check(pearl==(k==EldritchMob.Kind.LEADER?0:1)&&bags==(k==EldritchMob.Kind.PORTAL?0:1),"Wrong native boss loot "+k+" pearl="+pearl+" bags="+bags);}
  Thaumcraft.LOGGER.info("ELDRITCH56_NATIVE_LOOT_OK: native zombie AI base, giant anger and save, exact pearl and rare bag from actual deaths of all four new bosses/portal");
  for(int n=0;n<2;n++){var giant=new thaumcraft.taint.TaintedMob(thaumcraft.taint.TaintContent.MOBS.get(thaumcraft.taint.TaintedMob.Kind.GIANT).get(),l,thaumcraft.taint.TaintedMob.Kind.GIANT);giant.setNoAi(true);giant.setNoGravity(true);giant.setPos(P.getX()-20+n*3,P.getY(),P.getZ()+5);check(l.addFreshEntity(giant),"Cannot add giant taintacle");giants.add(giant);}
  var crab=mob(l,EldritchMob.Kind.CRAB,-18);var shell=tag(l,crab);shell.putInt("eldritch_phase",1);load(l,crab,shell);crab.getAttribute(Attributes.ARMOR).setBaseValue(5);crab.hurtServer(l,actor.damageSources().playerAttack(actor),10);check(crab.phase()==1&&crab.getHealth()>10,"Crab shell broke before armor was applied");crab.damageCooldownTime=0;crab.hurtServer(l,actor.damageSources().playerAttack(actor),3);check(crab.phase()==0&&crab.getAttributeBaseValue(Attributes.ARMOR)==0,"Crab shell did not break after actual half health");crab.discard();
  int brains=0,flesh=0;for(int n=0;n<64;n++){var zombie=new BrainyZombie(EldritchContent.ZOMBIES.get(EldritchMob.Kind.BRAINY).get(),l,EldritchMob.Kind.BRAINY);zombie.setNoAi(true);zombie.setPos(P.getX()-18,P.getY(),P.getZ()+3);zombie.getRandom().setSeed(5600+n);l.addFreshEntity(zombie);int start=joined.size();zombie.hurtServer(l,actor.damageSources().playerAttack(actor),100);int count=0;for(var dropped:joined.subList(start,joined.size()))if(dropped instanceof ItemEntity item){if(item.getItem().is(thaumcraft.infusion.CuriosityContent.BRAIN.get()))count+=item.getItem().getCount();if(item.getItem().is(Items.ROTTEN_FLESH))flesh+=item.getItem().getCount();}check(count<=1,"Generic zombie event duplicated brainy brain");brains+=count;}check(brains>0&&flesh>0,"Brainy/native zombie loot missing");Thaumcraft.LOGGER.info("ELDRITCH56_CRAB_ZOMBIE_OK: real armor threshold and 64 real zombie deaths, brains without duplicates and native zombie loot");
  var golem=mob(l,EldritchMob.Kind.GOLEM,-8);check(!golem.hurtServer(l,l.damageSources().magic(),401)&&golem.phase()==1&&golem.arrival()==100&&golem.isAlive(),"Golem phase transition failed");var clone=new EldritchMob(EldritchContent.TYPES.get(EldritchMob.Kind.GOLEM).get(),l,EldritchMob.Kind.GOLEM);load(l,clone,tag(l,golem));check(clone.phase()==1&&clone.arrival()==100,"Headless phase lost");golem.setTarget(actor);
  var inhabited=new BrainyZombie(EldritchContent.ZOMBIES.get(EldritchMob.Kind.INHABITED).get(),l,EldritchMob.Kind.INHABITED);inhabited.setNoAi(true);inhabited.setPos(P.getX()+8,P.getY(),P.getZ());l.addFreshEntity(inhabited);int before=joined.size();inhabited.hurtServer(l,l.damageSources().fellOutOfWorld(),100);inhabited.die(l.damageSources().fellOutOfWorld());check(joined.subList(before,joined.size()).stream().filter(e->e instanceof EldritchMob m&&m.kind==EldritchMob.Kind.CRAB).count()==1,"Inhabited zombie duplicated/lost crab");
  saved=mob(l,EldritchMob.Kind.WARDEN,-10);saved.setAbsorptionAmount(0);saved.hurtServer(l,l.damageSources().magic(),1);check(saved.frenzy()==150,"Warden frenzy did not trigger");saved.setTarget(actor);savedId=saved.getUUID();FilesWrite("eldritch-proof56.txt",savedId.toString());
  var portal=mob(l,EldritchMob.Kind.PORTAL,10);var t=tag(l,portal);t.putInt("eldritch_stage",12);t.putInt("eldritch_stage_ticks",0);load(l,portal,t);portal.tick();check(portal.stage()==13&&joined.stream().anyMatch(e->e instanceof EldritchMob m&&m.kind==EldritchMob.Kind.LEADER),"Portal did not spawn praetor");var rt=tag(l,portal);var restored=new EldritchMob(EldritchContent.TYPES.get(EldritchMob.Kind.PORTAL).get(),l,EldritchMob.Kind.PORTAL);load(l,restored,rt);check(restored.stage()==13,"Portal phase lost");portal.discard();
  check(SapField.place(l,P.west(20)),"Cannot place sap field");check(!SapField.place(l,P.below()),"Sap overwrote terrain");
  var firebat=new FireBat(EldritchContent.FIREBAT.get(),l);firebat.setPos(P.getX(),P.getY()+1,P.getZ()+6);l.addFreshEntity(firebat);
  var wuss=mob(l,EldritchMob.Kind.CRAB,20);thaumcraft.config.ThaumcraftConfig.wussMode.set(true);wuss.tick();check(wuss.isRemoved(),"Wuss ignored");thaumcraft.config.ThaumcraftConfig.wussMode.set(false);
  Thaumcraft.LOGGER.info("ELDRITCH56_NATIVE_RULES_OK: all attributes and registered biomes, nine eggs, NBT, golem phase, one released crab, Warden frenzy, real portal praetor and wuss");
 }
 static void FilesWrite(String p,String s){try{Files.writeString(Path.of(p),s);}catch(Exception e){throw new RuntimeException(e);}}
 @SubscribeEvent public static void tick(TickEvent.ServerTickEvent.Post e){if(mode().isEmpty()||stage==99)return;var l=e.server().overworld();ticks++;if(ticks==1)force(l);
  if(mode().equals("client")){if(actor==null)return;if(stage==0&&ticks>100){scene(l);stage=1;}if(stage==1&&Files.exists(Path.of("../work/eldritch56-creatures"))){actor.teleportTo(l,P.getX()-12,P.getY()+1,P.getZ()+9,Set.of(),180,12,true);stage=2;Thaumcraft.LOGGER.info("ELDRITCH56_CLIENT_CREATURES_READY: closer inspection of zombies, firebat and crab");}if(stage==2&&Files.exists(Path.of("../work/eldritch56-bosses"))){actor.teleportTo(l,P.getX()+10,P.getY()+2,P.getZ()+12,Set.of(),180,12,true);stage=3;Thaumcraft.LOGGER.info("ELDRITCH56_CLIENT_BOSSES_READY: closer inspection of the praetor, construct, Warden and greater portal");}return;}
  if(mode().equals("read")){if(ticks<100)return;try{savedId=UUID.fromString(Files.readString(Path.of("eldritch-proof56.txt")));saved=(EldritchMob)l.getEntity(savedId);check(saved!=null&&saved.kind==EldritchMob.Kind.WARDEN&&saved.getAttributeValue(Attributes.MAX_ABSORPTION)==264,"Warden missing after restart");thaumcraft.config.ThaumcraftConfig.allowSpawnElder.set(false);check(!SpawnPlacements.checkSpawnRules(WarpCreatures.GUARDIAN.get(),l,EntitySpawnReason.NATURAL,P.east(24),net.minecraft.util.RandomSource.create(56)),"Disabled guardian natural spawning");thaumcraft.config.ThaumcraftConfig.allowSpawnElder.set(true);check(SpawnPlacements.checkSpawnRules(WarpCreatures.GUARDIAN.get(),l,EntitySpawnReason.NATURAL,P.east(24),net.minecraft.util.RandomSource.create(56)),"Guardian original daylight rule not retained");Thaumcraft.LOGGER.info("ELDRITCH56_RESTART_OK: real saved Warden and shield capacity recovered in another process");}catch(Exception x){throw new RuntimeException(x);}stage=99;e.server().halt(false);return;}
  if(stage==0&&ticks>100){actor=fake(l);for(var p:BlockPos.betweenClosed(P.offset(-24,-1,-12),P.offset(24,-1,12)))l.setBlockAndUpdate(p,Blocks.STONE_BRICKS.defaultBlockState());rules(l);stage=1;return;}
  if(stage==1&&!giantLoot&&ticks>220){for(int index=0;index<2;index++){int before=joined.size();var victim=giants.get(index);for(int n=0;n<30&&victim.isAlive();n++){victim.damageCooldownTime=0;victim.hurtServer(l,l.damageSources().fellOutOfWorld(),35);}long pearls=joined.subList(before,joined.size()).stream().filter(x->x instanceof ItemEntity item&&item.getItem().is(thaumcraft.content.SimpleContent.ITEMS.get("primordial_pearl").get())).count();check(pearls==index,"Last taintacle pearl guard failed "+index+" pearls="+pearls);}giantLoot=true;Thaumcraft.LOGGER.info("ELDRITCH56_TAINTACLE_LOOT_OK: two real giant deaths, zero pearls before last, exactly one at last death");}
  if(stage==1&&ticks>600){check(saved.frenzy()==0&&saved.getAbsorptionAmount()>0,"Warden frenzy or shield regeneration stuck");check(!l.getBlockState(P.west(20)).is(thaumcraft.eldritch.EldritchContent.SAP.get()),"Sap field did not expire");check(joined.stream().anyMatch(e1->e1 instanceof ClericOrb orb&&orb.getOwner() instanceof EldritchMob m&&m.kind==EldritchMob.Kind.GOLEM),"Headless golem never fired actual orb");Thaumcraft.LOGGER.info("ELDRITCH56_NATIVE_TICKS_OK: frenzy completed, shield regenerated; saving real entities");stage=99;e.server().halt(false);}
 }
 @SubscribeEvent public static void login(net.minecraftforge.event.entity.player.PlayerEvent.PlayerLoggedInEvent e){if(mode().equals("client")&&e.getEntity() instanceof ServerPlayer p)actor=p;}
 static void scene(ServerLevel l){for(var old:l.getEntitiesOfClass(Entity.class,new net.minecraft.world.phys.AABB(P).inflate(70),entity->entity!=actor))old.discard();for(var p:BlockPos.betweenClosed(P.offset(-30,-1,-10),P.offset(30,5,10)))l.setBlockAndUpdate(p,p.getY()==P.getY()-1?Blocks.STONE_BRICKS.defaultBlockState():Blocks.AIR.defaultBlockState());for(var k:EldritchContent.TYPES.keySet()){var m=mob(l,k,k.ordinal()*5-18);m.setCustomName(net.minecraft.network.chat.Component.translatable("entity.thaumcraft."+k.id));m.setCustomNameVisible(true);}for(var k:EldritchContent.ZOMBIES.keySet()){var z=new BrainyZombie(EldritchContent.ZOMBIES.get(k).get(),l,k);z.setNoAi(true);z.setNoGravity(true);z.setPos(P.getX()+k.ordinal()*5-18,P.getY(),P.getZ());l.addFreshEntity(z);}var bat=new FireBat(EldritchContent.FIREBAT.get(),l);bat.setPos(P.getX()-23,P.getY()+1,P.getZ());bat.setNoAi(true);bat.setNoGravity(true);l.addFreshEntity(bat);actor.setGameMode(net.minecraft.world.level.GameType.CREATIVE);actor.teleportTo(l,P.getX(),P.getY()+4,P.getZ()+25,Set.of(),180,12,true);actor.getAbilities().flying=true;actor.onUpdateAbilities();l.getServer().clockManager().setTotalTicks(l.dimensionType().defaultClock().orElseThrow(),6000);actor.addEffect(new net.minecraft.world.effect.MobEffectInstance(net.minecraft.world.effect.MobEffects.NIGHT_VISION,12000,0,false,false));ready=true;Thaumcraft.LOGGER.info("ELDRITCH56_CLIENT_SCENE_READY: real registered creatures, boss bars, original geometry and textures");}
}
